// src/i18n/index.ts
var applyLocale = (path, locale) => {
  const prefix = localePrefix(locale);
  if (path === "/") return prefix || "/";
  return `${prefix}${path}`;
};
var localizedHomePath = (locale) => locale === DEFAULT_LOCALE ? "/" : `/${locale}`;
var buildHreflang = (toolId, siteUrl, contentPathForLocale) => {
  const locales = ["en", "pt-br", "id", "es-mx", "es-co", "de", "fr", "it"];
  const entries = locales.map((code) => {
    const cfg = localeByCode(code);
    const href = `${siteUrl}${contentPathForLocale(code)}`;
    return { hreflang: cfg.htmlLang, href };
  });
  const defaultEntry = entries.find((e) => e.hreflang === "en");
  entries.push({ hreflang: "x-default", href: defaultEntry.href });
  return entries;
};
var ALL_LOCALES = ["en", "pt-br", "id", "es-mx", "es-co", "de", "fr", "it"];

// src/router.ts
var STATIC_PATHS = {
  "/": { type: "home" },
  "/services": { type: "services" },
  "/about": { type: "about" },
  "/privacy": { type: "privacy" },
  "/terms": { type: "terms" },
  "/security": { type: "security" },
  "/cookies": { type: "cookies" },
  "/contact": { type: "contact" },
  "/site-audit": { type: "audit" },
  "/blog": { type: "blog" },
  "/pdf": { type: "seo-page", id: "pdf" },
  "/json": { type: "seo-page", id: "json" },
  "/image": { type: "seo-page", id: "image" },
  "/css": { type: "seo-page", id: "css" },
  "/dev": { type: "seo-page", id: "dev" },
  "/seo": { type: "seo-page", id: "seo" }
};
var viewToPath = (view, locale = DEFAULT_LOCALE) => {
  let path;
  switch (view.type) {
    case "home":
      path = "/";
      break;
    case "studio":
      path = "/";
      break;
    case "tool":
      path = `/tools/${localizedToolSlug(view.id, locale, view.id)}`;
      break;
    case "seo-page": {
      const entry = SEO_PAGE_MAP[view.id];
      path = entry ? entry.path : `/${view.id}`;
      break;
    }
    case "translator-pair":
      path = translatorPairPath(view.pair);
      break;
    case "comparison-page": {
      const entry = COMPARISON_PAGE_MAP[view.id];
      path = entry ? entry.path : `/compare/${view.id}`;
      break;
    }
    case "category-best": {
      const entry = CATEGORY_BEST_MAP[view.id];
      path = entry ? entry.path : `/${view.id}/best`;
      break;
    }
    case "about":
      path = "/about";
      break;
    case "services":
      path = "/services";
      break;
    case "privacy":
      path = "/privacy";
      break;
    case "terms":
      path = "/terms";
      break;
    case "security":
      path = "/security";
      break;
    case "cookies":
      path = "/cookies";
      break;
    case "contact":
      path = "/contact";
      break;
    case "audit":
      path = "/site-audit";
      break;
    case "color-studio":
      path = view.section === "home" ? "/studios/color" : `/studios/color/${view.section}`;
      break;
    case "color-page":
      path = view.kind === "color" ? `/colors/${view.id}` : view.kind === "palette" ? `/color-palettes/${view.id}` : `/ui-colors/${view.id}`;
      break;
    case "blog":
      path = "/blog";
      break;
    case "blog-article":
      path = `/blog/${view.slug}`;
      break;
    case "notFound":
      path = "/404";
      break;
    default:
      path = "/";
  }
  return applyLocale(path, locale);
};

