var seoEntryToMetadata = (toolId, entry, rootUrl) => {
  const meta = toolsRegistry[toolId];
  const related = (entry.related ?? []).filter((id) => Boolean(toolsRegistry[id])).map((id) => ({
    id,
    name: toolsRegistry[id]?.name ?? id,
    description: toolsRegistry[id]?.desc ?? ""
  }));
  return {
    title: entry.title,
    description: entry.description,
    canonicalUrl: `${rootUrl}/tools/${toolId}`,
    ogType: "website",
    breadcrumb: [
      { name: meta?.category || "All Tools", url: `${rootUrl}/` },
      { name: meta?.name || toolId, url: `${rootUrl}/tools/${toolId}` }
    ],
    faqs: entry.faqs,
    related,
    privacyExplanation: entry.privacyExplanation ?? "This tool runs entirely in your browser. Your files are processed locally and never uploaded to a server.",
    limitations: entry.limitations ?? [],
    detailedContent: {
      whatText: entry.whatText ?? entry.intro ?? entry.description,
      whyText: entry.whyText ?? "",
      features: entry.features ?? [],
      steps: entry.steps ?? [],
      examples: [],
      mistakes: []
    }
  };
};
var withFaqBoost = (toolId, entry) => {
  const boost = EXTRA_FAQS[toolId];
  if (!boost?.length) return entry;
  const seen = new Set((entry.faqs ?? []).map((f) => f.question));
  const merged = [...entry.faqs ?? [], ...boost.filter((f) => !seen.has(f.question))];
  return { ...entry, faqs: merged };
};
