    "es-co": { title: "Comprimir Imagen Online Gratis \u2013 Reducir Tama\xF1o de la Imagen", metaDescription: "Comprime im\xE1genes JPG, PNG y WebP online gratis y reduce su tama\xF1o sin perder calidad.", h1: "Comprimir Imagen", primaryKeyword: "comprimir imagen", secondaryKeywords: ["comprimir imagen online", "reducir peso imagen"], questions: ["\xBFC\xF3mo comprimir una imagen?"], faqs: [{ question: "\xBFC\xF3mo comprimo una imagen?", answer: "Carga la imagen, ajusta la calidad y descarga el resultado." }] },
    de: { title: "Bild komprimieren \u2013 Kostenlos Online Bildgr\xF6\xDFe reduzieren", metaDescription: "Komprimieren Sie JPG-, PNG- und WebP-Bilder online kostenlos und reduzieren Sie die Dateigr\xF6\xDFe.", h1: "Bild komprimieren", primaryKeyword: "bild komprimieren", secondaryKeywords: ["bild verkleinern", "bildgr\xF6\xDFe reduzieren", "bild online komprimieren"], questions: ["Wie komprimiere ich ein Bild?"], faqs: [{ question: "Wie komprimiere ich ein Bild online?", answer: "Laden Sie das Bild hoch, w\xE4hlen Sie die Qualit\xE4t und laden Sie es herunter." }] },
    fr: { title: "Compresser une image en ligne gratuit \u2013 R\xE9duire la taille", metaDescription: "Compressez des images JPG, PNG et WebP en ligne gratuitement.", h1: "Compresser une image", primaryKeyword: "compresser une image", secondaryKeywords: ["compresser image", "r\xE9duire taille image", "compresser photo"], questions: ["Comment compresser une image ?"], faqs: [{ question: "Comment compresser une image en ligne ?", answer: "Envoyez l'image, choisissez la qualit\xE9 et t\xE9l\xE9chargez le r\xE9sultat." }] },
    it: { title: "Comprimere Immagine Online Gratis \u2013 Ridurre Peso Immagine", metaDescription: "Comprimi immagini JPG, PNG e WebP online gratis riducendo il peso senza perdere qualit\xE0.", h1: "Comprimere immagine", primaryKeyword: "comprimere immagine", secondaryKeywords: ["comprimere immagine online", "ridurre peso immagine"], questions: ["Come comprimere un'immagine?"], faqs: [{ question: "Come comprimo un'immagine online?", answer: "Carica l'immagine, regola la qualit\xE0 e scarica il risultato." }] }
